51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE = 0.1;
53	const BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	
62	// Intermediate amounts are kept as fractions; only the final figure is rounded.
63	// Binary floating point makes sums like 100 * 1.1 + 5 land on 115.00000000000001,
64	// so that noise is trimmed before rounding.
65	const withoutFloatingPointNoise = (amount: number): number =>
66	  Number(amount.toPrecision(12));
67	
68	// Rounding always favours MHPCO, which means up for what the customer pays.
69	const roundPremiumInMHPCOsFavor = (amount: number): number =>
70	  Math.ceil(withoutFloatingPointNoise(amount));
71	
72	// Three alike components form a building block priced as a unit.
73	// "Alike" means the same item type, so each group below is one candidate block
74	// and a list may contain several blocks.
75	const BLOCK_SIZE = 3;
76	const BLOCK_BASE_PREMIUM = 60;
77	
78	const alikeGroupsOf = (items: Item[]): Item[][] => {
79	  const groups = new Map<string, Item[]>();
80	  for (const item of items) {
81	    const alike = groups.get(item.type);
82	    if (alike) alike.push(item);
83	    else groups.set(item.type, [item]);
84	  }
85	  return [...groups.values()];
86	};
87	
88	const formsABlock = (group: Item[]): boolean => group.length === BLOCK_SIZE;
89	
90	const sumOfIndividualBasePremiums = (items: Item[]): number =>
91	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
92	
93	const basePremiumOfGroup = (group: Item[]): number =>
94	  formsABlock(group) ? BLOCK_BASE_PREMIUM : sumOfIndividualBasePremiums(group);
95	
96	const basePremiumOf = (items: Item[]): number =>
97	  alikeGroupsOf(items).reduce(
98	    (sum, group) => sum + basePremiumOfGroup(group),
99	    0,
100	  );
101	
102	const CURSE_SURCHARGE = 0.5;
103	
104	// Item-specific surcharges are charged on the affected item's own base premium,
105	// not on the policy total.
106	const itemSurchargesOf = (items: Item[]): number =>
107	  items.reduce(
108	    (sum, item) =>
109	      sum + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE : 0),
110	    0,
111	  );
112	
113	const increasedBy = (amount: number, rate: number): number =>
114	  amount * (1 + rate);
115	
116	const firstInsuranceSurchargeOn = (policyBase: number): number =>
117	  policyBase * FIRST_INSURANCE_SURCHARGE;
118	
119	const withProcessingFee = (amount: number): number => amount + PROCESSING_FEE;
120	
121	// Item-specific modifiers are charged on the affected item's base premium;
122	// policy-wide modifiers are charged on the policy base premium (the sum of all
123	// item base premiums); the processing fee is added at the very end.
124	const premiumFor = (items: Item[]): number => {
125	  const policyBase = basePremiumOf(items);
126	  const beforeFee =
127	    policyBase +
128	    itemSurchargesOf(items) +
129	    firstInsuranceSurchargeOn(policyBase);
130	  return roundPremiumInMHPCOsFavor(withProcessingFee(beforeFee));
131	};
132	
133	const quoteFor = (step: QuoteStep): QuoteResult => ({
134	  premium: premiumFor(step.items),
135	});
136	
137	const resultOf = (step: Step): Result => {
138	  if (step.op === "quote") return quoteFor(step);
139	  throw new Error(`Unsupported step: ${step.op}`);
140	};
141	
142	export const runScenario = (scenario: Scenario): ScenarioResults => ({
143	  results: scenario.steps.map(resultOf),
144	});
